#!/usr/bin/env python3
"""Evaluate report coverage, never infer audit completion from field presence."""
import json,re,datetime,collections
from pathlib import Path
root=Path(__file__).resolve().parents[1]
request=(root/'evidence/request.md').read_text()
section=request.split('# DEFINICIÓN DE COMPLETITUD DEL /goal',1)[1].split('# ESTRATEGIA DE EJECUCIÓN',1)[0]
items=re.findall(r'^- \[ \] (.+?)[;.]?$',section,re.M)
data={p.stem:json.loads(p.read_text()) for p in (root/'data').glob('*.json') if p.stem!='completion-coverage'}
feature_counts=collections.Counter(row.get('status','UNKNOWN') for row in data.get('feature-matrix',{}).get('features',[]))
feature_count_text='/'.join(f'{count} {status}' for status,count in sorted(feature_counts.items()))
api_coverage=data.get('endpoint-supplement',{}).get('coverage',{})
api_inventory=data.get('backend-audit',{}).get('endpoints',[])
api_runtime=sum('registration' in row for row in api_inventory)
api_declarations=len(api_inventory)-api_runtime
effective_permission_count=len(data.get('effective-permissions',{}).get('permissions',[]))
web_coverage=data.get('web-semantic-audit',{}).get('coverage',{})
def profile(item):
 lower=item.lower()
 if 'inventario de documentación' in lower:return ['data/docs-governance.json#documents'],'INVENTORIED','371 documentos indexados y vinculados a revisión semántica por familias; alcance exacto: árbol rastreado del SHA, no documentos externos.'
 if 'auditoría de documentación' in lower or 'documentación vs' in lower:return ['data/docs-semantic-audit.json#documents','data/docs-semantic-audit.json#families','data/docs-semantic-audit.json#findings','evidence/docs-semantic-audit.md'],'FAMILY_SEMANTIC_REVIEW_PERFORMED','371 archivos leídos para claims/metadatos y clasificados mediante 15 familias y contraste de afirmaciones seleccionadas. No es certificación de cada frase ni reejecución de toda evidencia histórica; ver readScope y rationale por documento.'
 if 'inventario de módulos' in lower:return ['data/backend-audit.json#modules','data/synthesis.json#productMap'],'INVENTORIED','151 archivos backend declarados por capa; no equivale a inventario semántico completo de todos los bounded contexts ni revisión de todos los servicios.'
 if 'inventario de funcionalidades' in lower or 'feature matrix' in lower:return ['data/feature-matrix.json#features','data/docs-governance.json#features','data/sketchup-audit.json#features'],'SOURCE_MATRIX_RUNTIME_UNKNOWN',f'204 entradas enriquecidas por fuente:{feature_count_text} más seis capacidades SketchUp. Cada fila tiene fragmento semántico o alcance de postergación revisado; esto no cumple automáticamente todos los criterios o pruebas de capas. Cero funcionalidades COMPLETE acreditadas. Ver fieldCoverage y auditDepth.'
 if 'inventario de pantallas' in lower:return ['data/web-inventory.json#screens','data/web-inventory.json#secondaryInterfaces'],'INVENTORIED','29 rutas primarias, 259 interfaces secundarias y patrones adicionales. Hallazgo mecánico de componente no demuestra cobertura de toda interacción condicional.'
 if 'pantalla por pantalla' in lower or 'frontend' in lower or 'UX/UI' in item:return ['data/web-inventory.json','data/web-semantic-audit.json','data/runtime-ui.json','evidence/web-audit.md'],'STATIC_PLUS_LIMITED_RUNTIME',f'29 pantallas con fragmentos semánticos y26cuerpos de tests inspeccionados;259secundarios/140inline con profundidad por fila. Sin contexto semántico específico: secundarios{web_coverage.get("secondaryOnlyPendingNoSemanticContext","UNKNOWN")}, inline{web_coverage.get("inlineOnlyPendingNoSemanticContext","UNKNOWN")}; contratos compartidos no certifican cada consumidor. Navegación guest y algunas vistas/estados ejercitados; no se ejecutaron todos los formularios, roles, estados, responsive y flujos backend por pantalla.'
 if 'endpoints' in lower:return ['data/backend-audit.json#endpoints','data/endpoint-deep-audit.json#endpoints','data/endpoint-supplement.json#endpoints'],'MIXED_INVENTORY_AND_BOUNDED_HANDLER_REVIEW',f'{len(api_inventory)} registros mixtos: {api_runtime} registros runtime (incluidos wildcards/health) + {api_declarations} declaraciones OpenAPI/aliases; no son endpoints runtime distintos. 21 filas profundas + {api_coverage.get("supplementRows",0)} suplementarias; {api_coverage.get("combinedSemanticRows","UNKNOWN")} revisiones semánticas acotadas + {api_coverage.get("futureDeclarationsReviewed",0)} declaraciones futuras revisadas como scope; {api_coverage.get("remainingUnreviewedRows","UNKNOWN")} sin disposición revisada. Declaración futura no es handler implementado. No prueban cada caller, DTO, side effect ni matriz HTTP.'
 if 'backend' in lower:return ['data/backend-audit.json','data/endpoint-supplement.json','data/defect-proofs.json'],'TARGETED_STATIC_AND_TESTS','Inventario de handlers/storage y defectos focalizados; proofs de fallo cliente/DXF no prueban cada endpoint Go ni cada transacción.'
 if 'sketchup' in lower:return ['data/sketchup-audit.json','evidence/native-host-verification.md'],'STATIC_REVIEW_RUNTIME_UNKNOWN','Arquitectura/contratos/edición/catálogo recorridos en código y suites Ruby. Host nativo TestUp, interacción undo/save-reopen, secure store y binding reales siguen sin ejecutar.'
 if 'integración' in lower or 'integration matrix' in lower or 'contract drift' in lower:return ['data/synthesis.json#integrationMatrix','data/synthesis.json#journeys','data/sketchup-audit.json','evidence/openapi-check.log'],'STATIC_REVIEW_RUNTIME_UNKNOWN','Matriz y cadenas A–E documentan rupturas. Check generado prueba drift de generación, no toda paridad legacy. Falta recorrido bidireccional Web/Go/SketchUp del mismo ID y revisión.'
 if 'modelo de dominio' in lower:return ['data/synthesis.json#graphs','data/synthesis.json#domainInvariants'],'TARGETED_STATIC_REVIEW','Grafos y ownership contrastados para contextos críticos; no revisión semántica de cada entidad/regla del repositorio.'
 if 'base de datos' in lower:return ['data/database-deep-audit.json','data/backend-audit.json#migrations','evidence/database-deep-audit.md','evidence/pilot-foundation-proof.log'],'FINAL_SCHEMA_METADATA_AND_SEMANTIC_REVIEW','Metadata SELECT-only del esquema final:75 tablas public (74 aplicación/control +schema_migrations),842 columnas,435 constraints,279 índices,71 RLS enable+force,27 triggers,migración116;11 revisiones semánticas. Inventario histórico76 incluye2tablas retiradas y no schema_migrations. Sin consultar filas negocio: huérfanos reales, planes SQL/cargas y producción siguen no verificados.'
 if 'multitenancy' in lower:return ['evidence/pilot-foundation-proof.log','evidence/organization-browser.log','data/backend-audit.json'],'SCOPED_RUNTIME_VERIFIED','Foundation y cambio de tenant probados en alcance de sus tests. No acredita aislamiento de todos los uploads/jobs/exports/logs/SketchUp del producto.'
 if 'roles/permisos' in lower or 'permission matrix' in lower:return ['data/backend-audit.json#permissions','data/effective-permissions.json','data/synthesis.json#permissionsReference'],'STATIC_EFFECTIVE_COMPOSITION_RUNTIME_PARTIAL',f'536 filas role-only más{effective_permission_count}composiciones efectivas por familia recurso/acción, con credential/tenant/ownership/step-up y limitaciones. No son todas las permutaciones rol×estado ni denegaciones HTTP por cada celda.'
 if 'seguridad' in lower:return ['data/backend-audit.json#findings','data/operations-audit.json','evidence/pilot-foundation-proof.log'],'TARGETED_REVIEW','Auth/RLS y upload revisados; no pentest integral, consulta de advisories de dependencias, entorno productivo, explotación IDOR/XSS/CSRF por cada ruta.'
 if 'tests' in lower or 'ci/cd' in lower:return ['data/operations-audit.json','evidence/main-checks.json','evidence/organization-browser.log','evidence/init-isolated-db.log'],'SCOPED_CHECKS_VERIFIED','Resultados acotados del SHA y revisión CI/operación. No cobertura semántica exhaustiva, escáner externo de supply chain ni deploy/restore real. Cachés y skips del init no se convierten en pruebas ejecutadas.'
 if '3d' in lower:return ['data/runtime-ui.json','data/guest-journey.json','evidence/guest-proyectar-390-measurements.json','evidence/guest-proyectar-768-measurements.json'],'STATIC_PLUS_LIMITED_RUNTIME','WebGL desktop/cámara, placement local y undo/redo ensayados; canvas cero en 390/768 observado. Falta drag/snap exhaustivo, carga compleja, profiling FPS y host real.'
 if any(k in lower for k in ['herrajes','perforaciones','cnc/exportación']):return ['data/sketchup-audit.json','data/defect-proofs.json','evidence/guest-hardware-editor-dom.txt'],'STATIC_PLUS_HAZARD_PROOFS','Modelo/editor genérico y defectos DXF/fallback reproducidos. No homologación SKU Blum, operación interactiva host ni import-readback de software/máquina real.'
 if any(k in lower for k in ['quotes','designs','furniture','production','installation']):return ['data/synthesis.json#journeys','data/guest-journey.json','data/quote-version-audit.json','data/operational-flows.json'],'PARTIAL_VERTICAL_REVIEW','Cadenas operativas revisadas y recorrido guest sintético cliente→cotización→placement→undo/redo→quoted→accepted→plant board ejecutado; defecto QV-01 de historial corroborado. Falta continuidad autoritativa API/PostgreSQL/host hasta release, producción e instalación; no contar estado comercial local como ejecución física.'
 if 'issues relevantes' in lower or 'prs relevantes' in lower:return ['data/docs-governance.json#issues','data/docs-governance.json#prs','data/docs-governance.json#githubScope'],'TARGETED_REVIEW_AND_METADATA','154 issues/100 PRs inventariados; metadatos y trackers críticos contrastados. No revisión completa de comentarios/diff de todos los issues/PRs; snapshot de metadata puede ser posterior al main auditado.'
 if 'navegación' in lower or 'javascript' in lower or 'html' in lower or 'css' in lower:return ['index.html','js/app.js','css/main.css','css/print.css','evidence/portal-static-qa.md','assets/portal-mobile.png'],'ARTIFACT_IMPLEMENTED_SCOPED_QA','Portal implementado; root verificó HTTP localhost desktop/móvil y búsqueda antes del último mapping. Último mapping sólo syntax/rutas estáticas: reintento browser bloqueado por error interno tras servidor reiniciado, no defecto demostrado del portal. Apertura file:// bloqueada por política del navegador de herramientas: runtime file:// UNKNOWN. No confundir portal completo con auditoría completa.'
 keymap={'risk register':'risks','technical debt':'technicalDebt','mvp gap':'mvpGaps','demo gap':'mvpGaps','demo blockers':'tasks','fastest safe':'fastestSafePath','roadmap':'roadmap','issue plan':'issuePlan','user manual':'userManual','demo playbook':'demoPlaybook','scorecard':'scorecard','executive summary':'executive','prioridades':'tasks'}
 for term,key in keymap.items():
  if term in lower:return ['data/synthesis.json#'+key,'evidence/synthesis.md'],'ARTIFACT_PRODUCED_NOT_EXECUTED','Contenido estructurado basado en evidencia e inferencia/propuesta explícitas. Recomendaciones, guion y bandas ordinales no acreditan implementación ni ensayo integral; consultar unknowns y gates.'
 return ['data/synthesis.json'],'NEEDS_VERIFICATION','No se encontró una asignación específica suficiente para este requisito; requiere revisión manual, no se marca cumplido.'
coverage=[]
for i,item in enumerate(items,1):
 refs,status,limit=profile(item)
 coverage.append({'id':f'DOD-{i:02d}','requirement':item.rstrip(';.'),'status':status,'evidence':[r for r in refs if (root/r.split('#')[0]).exists()],'missingArtifacts':[r for r in refs if not (root/r.split('#')[0]).exists()],'limitation':limit,'reviewPerformed':status!='NEEDS_VERIFICATION','auditDisposition':'BOUNDED_REVIEW_PERFORMED' if status!='NEEDS_VERIFICATION' else 'REVIEW_PENDING','goalCompletion':'ROOT_REQUIRES_ACCEPTANCE_REVIEW','completeMeaning':'Review performed and remaining verification are separate; this script does not decide goal completion.'})
# These aliases describe stored columns, not semantic equivalence or correctness.
schemas={
 'features':('feature-matrix' if 'feature-matrix' in data else 'docs-governance','features',{'ID':['id'],'Module':['module'],'Feature':['name','title'],'Description':['description'],'Users':['users'],'Status':['status'],'Frontend':['Frontend','frontend'],'Backend':['Backend','backend'],'SketchUp':['SketchUp','sketchup'],'Tests':['Tests','tests'],'Documentation':['documentation'],'Demo importance':['demoImportance'],'MVP importance':['mvpImportance'],'Problems':['problems'],'Recommendation':['recommendation'],'Related issues':['relatedIssues'],'Related PRs':['relatedPRs']}),
 'endpoints':('backend-audit','endpoints',{'METHOD':['method'],'PATH':['path'],'PURPOSE':['purpose'],'AUTH':['authorization'],'ROLES':['roles'],'TENANT':['tenant'],'INPUT':['input'],'VALIDATION':['validation'],'OUTPUT':['output'],'ERRORS':['errors'],'DOMAIN OBJECTS':['domainObjects'],'CALLERS':['callers'],'DEPENDENCIES':['dependencies'],'SIDE EFFECTS':['sideEffects'],'RELATED WEB SCREEN':['relatedWebScreen'],'RELATED SKETCHUP FUNCTION':['relatedSketchupFunction'],'TEST COVERAGE':['testCoverage'],'KNOWN PROBLEMS':['knownProblems']}),
 'screens':('web-inventory','screens',{'Nombre':['name'],'Ruta':['route'],'Objetivo':['objective'],'Usuario objetivo':['targetUser'],'Roles permitidos':['allowedRoles'],'Datos utilizados':['dataUsed'],'APIs utilizadas':['apisUsed'],'Estados':['states'],'Acciones principales':['primaryActions'],'Acciones secundarias':['secondaryActions'],'Navegación de entrada':['entryNavigation'],'Navegación de salida':['exitNavigation'],'Componentes relevantes':['relevantComponents'],'Loading state':['states.loading'],'Empty state':['states.empty'],'Error state':['states.error'],'Success state':['states.success'],'Validaciones':['validations'],'Responsive behavior':['responsiveBehavior'],'Permisos':['permissions'],'Problemas':['problems'],'Deuda':['debt'],'Mejoras':['improvements'],'Prioridad':['priority'],'Importancia para demo':['demoImportance']})}
if 'endpoint-deep-audit' in data:
 schemas['endpoints-deep']=('endpoint-deep-audit','endpoints',{'METHOD':['method'],'PATH':['path'],'PURPOSE':['purpose'],'AUTH':['authAndRoles'],'ROLES':['authAndRoles'],'TENANT':['tenantScope'],'INPUT':['input'],'VALIDATION':['validation'],'OUTPUT':['output'],'ERRORS':['errors'],'DOMAIN OBJECTS':['domain'],'CALLERS':['callers'],'DEPENDENCIES':['dependencies'],'SIDE EFFECTS':['sideEffects'],'RELATED WEB SCREEN':['webAndSketchUp'],'RELATED SKETCHUP FUNCTION':['webAndSketchUp'],'TEST COVERAGE':['tests'],'KNOWN PROBLEMS':['problems']})
if 'endpoint-supplement' in data:
 schemas['endpoints-supplement']=('endpoint-supplement','endpoints',{'METHOD':['method'],'PATH':['path'],'PURPOSE':['purpose'],'AUTH':['authAndRoles'],'ROLES':['authAndRoles'],'TENANT':['tenantScope'],'INPUT':['inputValidation'],'VALIDATION':['inputValidation'],'OUTPUT':['outputErrors'],'ERRORS':['outputErrors'],'DOMAIN OBJECTS':['domain'],'CALLERS':['callers'],'DEPENDENCIES':['storageDependenciesInventory'],'SIDE EFFECTS':['sideEffects'],'RELATED WEB SCREEN':['webAndSketchUp'],'RELATED SKETCHUP FUNCTION':['webAndSketchUp'],'TEST COVERAGE':['tests'],'KNOWN PROBLEMS':['unknowns']})
def get(row,path):
 for key in path.split('.'):
  if not isinstance(row,dict) or key not in row:return None
  row=row[key]
 return row
fields=[]
for title,(source,key,mapping) in schemas.items():
 rows=data[source][key]
 for field,aliases in mapping.items():
  vals=[next((get(r,a) for a in aliases if get(r,a) is not None),None) for r in rows]
  fields.append({'inventory':title,'source':source,'field':field,'rows':len(rows),'present':sum(v is not None for v in vals),'missing':sum(v is None for v in vals),'empty':sum(v==[] or v=={} or v=='' for v in vals),'explicitUnknown':sum(v is not None and bool(re.search(r'UNKNOWN|NEEDS VERIFICATION|NOT VERIFIED|not verified',json.dumps(v),re.I)) for v in vals),'aliasesChecked':aliases,'meaning':'Presence only; nested unknowns and source-signal extraction are not completed verification.'})
result={'snapshot':'316df57c7c3c9d5470b5a3f22b39fffeacfd7676','generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'overallStatus':'BOUNDED_REVIEW_DOCUMENTED; PRODUCT_RUNTIME_NOT_CERTIFIED','coverage':coverage,'fieldCoverage':fields,'limitations':['This is a gap report, not an automatic completion gate.','reviewPerformed acknowledges actual bounded review; missing runtime or acceptance evidence is stated separately, not a blanket claim that nothing was audited.','Endpoint handlerPermissionFunctions/storageMethods/declaredResponses are clues, not full role/side-effect/output audits.','Feature references do not replace explicit per-layer implementation, users, issues/PRs and test mapping.','Screen state tokens require semantically inspecting the control and executing its state; column presence alone is weak evidence.']}
(root/'data/completion-coverage.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
lines=['# Cobertura de auditoría acotada — no certificación integral del producto','',f'{len(coverage)} requisitos del checklist original mapeados. Ninguno se convierte automáticamente en completado por existir un archivo.','', '| ID | Requisito | Evidencia / nivel | Límite |','|---|---|---|---|']
for r in coverage:lines.append('| '+r['id']+' | '+r['requirement']+' | '+r['status']+'; '+', '.join(r['evidence'])+' | '+r['limitation']+(' Faltante: '+', '.join(r['missingArtifacts']) if r['missingArtifacts'] else '')+' |')
lines+=['','## Campos requeridos: faltantes reales','', 'Conteo estructural únicamente. Campos presentes con UNKNOWN o señales extraídas no están verificados.','', '| Inventario | Campo | Filas | Presente | Ausente | Vacío | UNKNOWN explícito |','|---|---|---:|---:|---:|---:|---:|']
for f in fields:lines.append(f"| {f['inventory']} | {f['field']} | {f['rows']} | {f['present']} | {f['missing']} | {f['empty']} | {f['explicitUnknown']} |")
(root/'evidence/completion-coverage.md').write_text('\n'.join(lines)+'\n')
print(f'Mapped {len(coverage)} checklist requirements; inspected {len(fields)} required column definitions. No completion certification.')
